xml.Script:
        W := 0.5;
        D := W * 0.25;

        procedure Prepare();
        begin
            Count := Length(S) div 3;
            for i := 0 to Count - 1 do begin
                ax[i] := StrToInt(copy(S, i * 3 + 1, 1));
                L[i] := StrToInt(copy(S, i * 3 + 2, 1));
                Sign := copy(S, i * 3 + 3, 1);
                if Sign = '-' then begin
                    FromL[i] := L[i] + 1;
                    ToL[i] := 20;
                end else begin
                    FromL[i] := 0;
                    ToL[i] := L[i];
                end;
            end;
        end;

xml.Figure:
        
        

        
            
            
             Inc(i); 
        
        
             Prepare; 
            
            
        

